    + `<div class="mt-2 flex flex-wrap gap-1.5">${n.opps.slice(0,4).map(p=>`<span class="text-xs text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-md px-2 py-0.5">${p}</span>`).join('')}</div>`
    + (n.note?`<p class="mono mt-4 text-[11px] text-slate-500">${n.note}</p>`:'')
    + `<button onclick="openLead('', '${n.name} package')" class="mono mt-5 w-full border border-slate-300 dark:border-white/15 hover:border-emerald-500 hover:text-emerald-700 dark:hover:text-emerald-300 font-bold py-2.5 rounded-xl text-[13px] transition">get_${n.code.toLowerCase()}_package</button></div>`;
}
function renderNiches(filter=''){
  const grid = document.getElementById('nicheGrid');
  const f = filter.toLowerCase().trim();
  const list = NICHES.filter(n => !f || (n.name+' '+n.tags+' '+n.prospects.join(' ')+' '+n.opps.join(' ')).toLowerCase().includes(f));
  let html = list.map(nicheCard).join('');
  html += `<div class="bg-slate-900 dark:bg-emerald-400/10 dark:border dark:border-emerald-400/30 rounded-2xl p-6 flex flex-col justify-center text-white">`
    + `<p class="mono text-[11px] text-emerald-400">niche_not_found?</p>`
    + `<h3 class="font-display font-bold text-xl mt-1">Don&rsquo;t See Your Industry?</h3>`
    + `<p class="text-sm mt-2 text-slate-300">Tell us what you sell and we will build a prospecting package around your market.</p>`
    + `<button onclick="openLead('', 'Custom niche')" class="mono mt-4 bg-emerald-500 hover:bg-emerald-400 text-[#0A1628] font-bold py-2.5 rounded-xl text-sm transition">tell_us_your_niche</button></div>`;
  if(!list.length) html = `<p class="text-slate-500 col-span-full py-8 mono text-sm">0 results. <button class="underline text-emerald-600 dark:text-emerald-400" onclick="openLead()">tell us your niche</button> and we will build around it.</p>` + html;
  grid.innerHTML = html;
}
renderNiches();
document.getElementById('nicheSearch').addEventListener('input', e=>renderNiches(e.target.value));
const sel = document.getElementById('leadNiche');
NICHES.forEach(n=>{ const o=document.createElement('option'); o.textContent=n.name; sel.appendChild(o); });
const other=document.createElement('option'); other.textContent='Other / Not listed'; sel.appendChild(other);
const modal=document.getElementById('leadModal');
function openLead(pkg='', msg=''){
  modal.classList.remove('hidden'); modal.classList.add('flex'); document.body.style.overflow='hidden';
  if(pkg){ const map={START:'START — UGX 250,000',GROW:'GROW — UGX 350,000',BUSINESS:'BUSINESS — UGX 650,000'}; document.getElementById('leadPackage').value = map[pkg]||pkg; }
  if(msg){ document.getElementById('leadMsg').value = 'I am interested in: '+msg; }
  document.getElementById('leadForm').classList.remove('hidden'); document.getElementById('leadSuccess').classList.add('hidden');
}
function closeLead(){ modal.classList.add('hidden'); modal.classList.remove('flex'); document.body.style.overflow=''; }
document.getElementById('leadForm').addEventListener('submit', e=>{ e.preventDefault(); document.getElementById('leadForm').classList.add('hidden'); document.getElementById('leadSuccess').classList.remove('hidden'); });
document.addEventListener('keydown', e=>{ if(e.key==='Escape') closeLead(); });
const menuBtn=document.getElementById('menuBtn'), mobileMenu=document.getElementById('mobileMenu'), mO=document.getElementById('menuOpen'), mC=document.getElementById('menuClose');
menuBtn.addEventListener('click', ()=>{ const open=mobileMenu.classList.toggle('hidden'); mO.classList.toggle('hidden',!open); mC.classList.toggle('hidden',open); });
mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{ mobileMenu.classList.add('hidden'); mO.classList.remove('hidden'); mC.classList.add('hidden'); }));
const io=new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target);} }),{threshold:.12});
document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
window.addEventListener('scroll',()=>{ document.getElementById('nav').style.boxShadow = window.scrollY>10 ? '0 8px 30px -12px rgba(10,22,40,.18)' : 'none'; });
function currentTheme(){ return document.documentElement.classList.contains('dark') ? 'dark' : 'light'; }
function paintThemeBtn(){ const dark=currentTheme()==='dark'; document.getElementById('iconMoon').classList.toggle('hidden',dark); document.getElementById('iconSun').classList.toggle('hidden',!dark); }
function toggleTheme(){ const next=currentTheme()==='dark'?'light':'dark'; document.documentElement.classList.toggle('dark',next==='dark'); try{localStorage.setItem('ttryy-theme',next);}catch(e){} paintThemeBtn(); }
paintThemeBtn();
</script>
</body>
</html>
